    Question(
      id: "sci_ch5_p90_q05",
      subject: Subject.science,
      chapterId: "sci_ch_05_life_processes",
      questionText: "[QUESTIONS (Page 90)] In the Modern Periodic Table, which elements among the first ten elements (atomic numbers 1 to 10) are metals?",
      options: const [
