    Question(
      id: "sci_ch5_p90_q06",
      subject: Subject.science,
      chapterId: "sci_ch_05_life_processes",
      questionText: "[QUESTIONS (Page 90)] By considering their positions in the Periodic Table, which of the following elements would you expect to have the maximum metallic characteristic: \$\\text{Ga}\$, \$\\text{Ge}\$, \$\\text{As}\$, \$\\text{Se}\$, or \$\\text{Be}\$?",
      options: const [
